-- Derived alternatives (docs/domain.md "Derived alternative", ADR 0013): a scenario records the
-- revision it was derived from, who derived it and when. Generated by drizzle-kit from
-- src/db/schema.ts, then by hand on scenarios_derived_from_revision_fkey: ON DELETE SET NULL
-- ("derived_from_revision_id"), since Drizzle cannot limit SET NULL to one column and nulling the
-- whole key would break organization_id, and DEFERRABLE INITIALLY DEFERRED, since a visitor's copy
-- inserts its scenarios before the revisions they name. derived_at stays, so an alternative whose
-- revision was deleted with its scenario still says it came from one.
ALTER TABLE "scenarios" ADD COLUMN "derived_from_revision_id" uuid;--> statement-breakpoint
ALTER TABLE "scenarios" ADD COLUMN "derived_by" uuid;--> statement-breakpoint
ALTER TABLE "scenarios" ADD COLUMN "derived_at" timestamp with time zone;--> statement-breakpoint
ALTER TABLE "scenarios" ADD CONSTRAINT "scenarios_derived_by_user_id_fk" FOREIGN KEY ("derived_by") REFERENCES "auth"."user"("id") ON DELETE set null ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "scenarios" ADD CONSTRAINT "scenarios_derived_from_revision_fkey" FOREIGN KEY ("organization_id","derived_from_revision_id") REFERENCES "public"."scenario_revision"("organization_id","id") ON DELETE SET NULL ("derived_from_revision_id") ON UPDATE no action DEFERRABLE INITIALLY DEFERRED;--> statement-breakpoint
CREATE INDEX "scenarios_derived_from_revision_idx" ON "scenarios" USING btree ("organization_id","derived_from_revision_id");--> statement-breakpoint
ALTER TABLE "scenarios" ADD CONSTRAINT "scenarios_derived_check" CHECK (derived_at is not null or (derived_from_revision_id is null and derived_by is null));
